export function deepClone<T>(value: T, seen = new Map<object, unknown>()): T {
  if (value === null || typeof value !== 'object') {
    return value;
  }

  // Handle circular references
  if (seen.has(value as object)) {
    return seen.get(value as object) as T;
  }

  // Handle Date objects
  if (value instanceof Date) {
    const dateCopy = new Date(value.getTime());
    seen.set(value as object, dateCopy);
    return dateCopy as unknown as T;
  }

  if (Array.isArray(value)) {
    const arrCopy: unknown[] = [];
    seen.set(value as object, arrCopy);
    for (const item of value) {
      arrCopy.push(deepClone(item, seen));
    }
    return arrCopy as unknown as T;
  }

  const result: Record<string, unknown> = {};
  seen.set(value as object, result);
  for (const key of Object.keys(value as Record<string, unknown>)) {
    result[key] = deepClone((value as Record<string, unknown>)[key], seen);
  }

  return result as T;
}

