/**
 * Processes a list of items by sending each to an async handler.
 * Returns an array of processed results in order.
 */
export async function processItems<T, R>(
  items: T[],
  handler: (item: T) => Promise<R>
): Promise<R[]> {
  const results: R[] = [];

  // Collect per-item promises and await them before returning.
  const promises = items.map(async (item) => {
    const result = await handler(item);
    return result;
  });

  const resolved = await Promise.all(promises);
  results.push(...resolved);

  return results;
}

/**
 * Simulates saving records to a database.
 * Returns the total number of records saved.
 */
export async function saveRecords(
  records: string[],
  saveFn: (record: string) => Promise<boolean>
): Promise<number> {
  let savedCount = 0;

  // Collect per-record promises and await them before returning.
  const promises = records.map(async (record) => {
    return saveFn(record);
  });

  const outcomes = await Promise.all(promises);
  for (const ok of outcomes) {
    if (ok) savedCount++;
  }

  return savedCount;
}

