/**
 * Deep clones a value, handling nested objects, arrays, Dates,
 * and circular references.
 */
export function deepClone<T>(value: T): T {
  const visited = new Map<unknown, unknown>();

  const cloneInner = (val: unknown): unknown => {
    if (val === null || typeof val !== 'object') return val;

    // Circular reference handling
    const existing = visited.get(val);
    if (existing) return existing;

    if (val instanceof Date) {
      const d = new Date(val.getTime());
      visited.set(val, d);
      return d;
    }

    if (Array.isArray(val)) {
      const arr: unknown[] = [];
      visited.set(val, arr);
      for (const item of val) arr.push(cloneInner(item));
      return arr;
    }

    // Plain object / class instances: create same prototype object
    const proto = Object.getPrototypeOf(val);
    const obj: Record<string, unknown> = Object.create(proto);
    visited.set(val, obj);

    for (const key of Object.keys(val as Record<string, unknown>)) {
      obj[key] = cloneInner((val as Record<string, unknown>)[key]);
    }

    return obj;
  };

  return cloneInner(value) as T;
}

/**
 * Deep equality check for two values.
 */
export function deepEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (typeof a !== typeof b) return false;

  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  if (typeof a !== 'object' || typeof b !== 'object') return false;

  const aObj = a as Record<string, unknown>;
  const bObj = b as Record<string, unknown>;

  const aKeys = Object.keys(aObj);
  const bKeys = Object.keys(bObj);
  if (aKeys.length !== bKeys.length) return false;

  return aKeys.every((key) => deepEqual(aObj[key], bObj[key]));
}

